prompt:
Add `rotate_left` to the existing unit `u3`: for a non-empty array, move every element one place to the left and the first element to the end (a[k] becomes old a[k + 1], the last element becomes old a[0]). The contract must state where every element goes.

Required signature (in unit `u3`):
fn rotate_left(a: &mut [i64]) -> ()

reference.code:
spec fn shifted_below(a: &[i64], b: &[i64], n: usize) -> bool {
    a.len() == b.len() && (forall|k: usize| k < a.len() ==> ((k < n ==> #[trigger] a[k] == b[k + 1]) && (k >= n ==> a[k] == b[k])))
}

spec fn rotated(a: &[i64], b: &[i64]) -> bool {
    a.len() == b.len() && a.len() > 0 && a[a.len() - 1] == b[0] && (forall|k: usize| k + 1 < a.len() ==> #[trigger] a[k] == b[k + 1])
}

#[effects(pure)]
#[uses(d030, shifted_below, rotated)]
fn rotate_left(a: &mut [i64]) -> ()
    requires d030(a),
    ensures rotated(a, old(a)),
{
    let t: i64 = a[0];
    let mut k: usize = 0;
    while k + 1 < a.len()
        invariant k < a.len(), t == old(a)[0], shifted_below(a, old(a), k),
        decreases a.len() - k,
    {
        a[k] = a[k + 1];
        k = k + 1;
    }
    a[k] = t;
}

